#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

DEF TS TimeSensor {
  enabled FALSE
  cycleInterval 2
}

DEF PI PositionInterpolator {
  key [
    0,
    1
  ]
  keyValue [
    0 0 0,
    1 1 1
  ]
}

DEF T Transform {
  children Shape {
    geometry Sphere { }
  }
}

ROUTE TS.fraction_changed TO PI.set_fraction
ROUTE PI.value_changed TO T.set_translation
